-- Generated by pwc2dbt from PowerCenter mapping m_FL_JS_MARTS_CORE, target ORDER_ITEMS.

with

sq_stg_order_items as (
    -- Source Qualifier SQ_STG_ORDER_ITEMS
    select
        stg_order_items.order_item_id,
        stg_order_items.order_id,
        stg_order_items.product_id
    from {{ ref('stg_order_items') }} as stg_order_items
),

sq_stg_orders as (
    -- Source Qualifier SQ_STG_ORDERS
    select
        stg_orders.order_id,
        stg_orders.customer_id,
        stg_orders.location_id,
        stg_orders.ordered_at_day,
        stg_orders.subtotal_cents,
        stg_orders.tax_paid_cents,
        stg_orders.order_total_cents,
        stg_orders.subtotal,
        stg_orders.tax_paid,
        stg_orders.order_total
    from {{ ref('stg_orders') }} as stg_orders
),

jnr_order_items_orders as (
    -- Joiner JNR_ORDER_ITEMS_ORDERS
    -- Normal Join (master sq_stg_orders, detail sq_stg_order_items)
    select
        sq_stg_order_items.order_item_id,
        sq_stg_order_items.order_id,
        sq_stg_order_items.product_id,
        sq_stg_orders.ordered_at_day
    from sq_stg_order_items
        inner join sq_stg_orders
            on sq_stg_orders.order_id = sq_stg_order_items.order_id
),

sq_stg_products1 as (
    -- Source Qualifier SQ_STG_PRODUCTS1
    select
        stg_products1.product_id,
        stg_products1.product_name,
        stg_products1.product_type,
        stg_products1.product_price_cents,
        stg_products1.product_price,
        stg_products1.product_description,
        stg_products1.is_food_item,
        stg_products1.is_drink_item
    from {{ ref('stg_products') }} as stg_products1
),

jnr_add_products as (
    -- Joiner JNR_ADD_PRODUCTS
    -- Normal Join (master sq_stg_products1, detail jnr_order_items_orders)
    select
        jnr_order_items_orders.order_item_id,
        jnr_order_items_orders.order_id,
        jnr_order_items_orders.product_id,
        jnr_order_items_orders.ordered_at_day,
        sq_stg_products1.product_name,
        sq_stg_products1.product_type,
        sq_stg_products1.product_price,
        sq_stg_products1.is_food_item,
        sq_stg_products1.is_drink_item
    from jnr_order_items_orders
        inner join sq_stg_products1
            on sq_stg_products1.product_id = jnr_order_items_orders.product_id
),

sq_stg_supplies1 as (
    -- Source Qualifier SQ_STG_SUPPLIES1
    select
        stg_supplies1.supply_id,
        stg_supplies1.supply_name,
        stg_supplies1.supply_cost_cents,
        stg_supplies1.supply_cost,
        stg_supplies1.is_perishable,
        stg_supplies1.product_id
    from {{ ref('stg_supplies') }} as stg_supplies1
),

srt_supplies as (
    -- Sorter SRT_SUPPLIES
    -- sort order dropped: a table or view has no row order
    select
        sq_stg_supplies1.supply_id,
        sq_stg_supplies1.supply_name,
        sq_stg_supplies1.supply_cost_cents,
        sq_stg_supplies1.supply_cost,
        sq_stg_supplies1.is_perishable,
        sq_stg_supplies1.product_id
    from sq_stg_supplies1
),

agg_supplies_by_product as (
    -- Aggregator AGG_SUPPLIES_BY_PRODUCT
    select
        srt_supplies.product_id,
        sum(srt_supplies.supply_cost) as supply_cost_per_product,
        max(srt_supplies.is_perishable) as has_perishable_supply
    from srt_supplies
    group by srt_supplies.product_id
),

jnr_add_supply_cost as (
    -- Joiner JNR_ADD_SUPPLY_COST
    -- Master Outer Join (master jnr_add_products, detail agg_supplies_by_product)
    select
        jnr_add_products.order_item_id,
        jnr_add_products.order_id,
        agg_supplies_by_product.product_id,
        jnr_add_products.ordered_at_day,
        jnr_add_products.product_name,
        jnr_add_products.product_type,
        jnr_add_products.product_price,
        jnr_add_products.is_food_item,
        jnr_add_products.is_drink_item,
        agg_supplies_by_product.supply_cost_per_product,
        agg_supplies_by_product.has_perishable_supply
    from agg_supplies_by_product
        left join jnr_add_products
            on jnr_add_products.product_id = agg_supplies_by_product.product_id
),

exp_order_items_calc as (
    -- Expression EXP_ORDER_ITEMS_CALC
    select
        jnr_add_supply_cost.order_item_id,
        jnr_add_supply_cost.order_id,
        jnr_add_supply_cost.product_id,
        jnr_add_supply_cost.ordered_at_day,
        jnr_add_supply_cost.product_name,
        jnr_add_supply_cost.product_type,
        jnr_add_supply_cost.product_price,
        jnr_add_supply_cost.is_food_item,
        jnr_add_supply_cost.is_drink_item,
        coalesce(jnr_add_supply_cost.supply_cost_per_product, 0) as supply_cost_per_product,
        coalesce(jnr_add_supply_cost.has_perishable_supply, 0) as has_perishable_supply
    from jnr_add_supply_cost
)

select
    exp_order_items_calc.order_item_id,
    exp_order_items_calc.order_id,
    exp_order_items_calc.product_id,
    exp_order_items_calc.ordered_at_day,
    exp_order_items_calc.product_name,
    exp_order_items_calc.product_type,
    exp_order_items_calc.product_price,
    exp_order_items_calc.is_food_item,
    exp_order_items_calc.is_drink_item,
    exp_order_items_calc.supply_cost_per_product,
    exp_order_items_calc.has_perishable_supply
from exp_order_items_calc
